package com.ruoyi.framework.audit;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import java.time.*;import java.nio.file.*;import java.io.*;import java.util.zip.*;import java.security.MessageDigest;import com.alibaba.fastjson2.JSON;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.PlatformTransactionManager;
class AuditRetentionTest{
 @TempDir Path root;
 private List<Map<String,Object>> records(int count,long start){List<Map<String,Object>> rows=new ArrayList<>();for(int i=0;i<count;i++)rows.add(Map.of("oper_id",start+i,"password","FAKE_PASSWORD","nested",Collections.nCopies(150,Map.of("number",i,"token","FAKE_TOKEN"))));return rows;}
 private AuditRetention service(JdbcTemplate jdbc){return new AuditRetention(jdbc,mock(PlatformTransactionManager.class));}
 private void deleteCounts(JdbcTemplate j){when(j.update(anyString())).thenAnswer(call->{String sql=call.getArgument(0);return sql.substring(sql.indexOf(" IN (")+5,sql.length()-1).split(",").length;});}
 private int verifyFiles()throws Exception{int count=0;try(var files=Files.list(root)){for(Path manifest:files.filter(p->p.toString().endsWith(".manifest.json")).toList()){var meta=JSON.parseObject(Files.readString(manifest));byte[] data;try(var zip=new GZIPInputStream(Files.newInputStream(root.resolve(meta.getString("file"))))){data=zip.readAllBytes();}var rows=JSON.parseArray(new String(data,java.nio.charset.StandardCharsets.UTF_8));assertEquals(meta.getIntValue("rows"),rows.size());assertEquals(meta.getList("ids",String.class),rows.stream().map(r->((Map<?,?>)r).get("oper_id").toString()).toList());assertEquals(meta.getString("sha256"),HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data)));assertEquals(150,((List<?>)((Map<?,?>)rows.get(0)).get("nested")).size());assertFalse(new String(data,java.nio.charset.StandardCharsets.UTF_8).contains("FAKE_"));count+=rows.size();}}return count;}
 @Test void archives101RecordsCompletely()throws Exception{JdbcTemplate j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenReturn(records(101,1),List.of());deleteCounts(j);service(j).archive("sys_oper_log","oper_id","oper_time",LocalDate.now(),root);assertEquals(101,verifyFiles());verify(j).update(startsWith("DELETE FROM sys_oper_log"));}
 @Test void archives1000AndNextBatchCompletely()throws Exception{JdbcTemplate j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenReturn(records(1000,1),records(101,1001),List.of());deleteCounts(j);service(j).archive("sys_oper_log","oper_id","oper_time",LocalDate.now(),root);assertEquals(1101,verifyFiles());verify(j,times(2)).update(startsWith("DELETE FROM sys_oper_log"));}
 @Test void archiveFailureNeverDeletesDatabaseRows()throws Exception{JdbcTemplate j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenReturn(records(1,1));Path invalid=Files.createTempFile(root,"invalid",".tmp");assertThrows(IllegalStateException.class,()->service(j).archive("sys_oper_log","oper_id","oper_time",LocalDate.now(),invalid));verify(j,never()).update(startsWith("DELETE"));}
 @Test void verificationFailureNeverDeletesDatabaseRows()throws Exception{JdbcTemplate j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenReturn(records(101,1));AuditRetention service=spy(service(j));doThrow(new IOException("verification failed")).when(service).verifyArchive(any(),anyString(),anyList(),anyString());assertThrows(IllegalStateException.class,()->service.archive("sys_oper_log","oper_id","oper_time",LocalDate.now(),root));verify(j,never()).update(startsWith("DELETE"));}
 @Test void manifestFailureNeverDeletesDatabaseRows()throws Exception{JdbcTemplate j=mock(JdbcTemplate.class);when(j.queryForList(anyString(),any(Object[].class))).thenReturn(records(101,1));AuditRetention service=spy(service(j));doThrow(new IOException("manifest failed")).when(service).writeManifest(any(),anyMap());assertThrows(IllegalStateException.class,()->service.archive("sys_oper_log","oper_id","oper_time",LocalDate.now(),root));verify(j,never()).update(startsWith("DELETE"));}
 @Test void rejectsWrongHashCountAndIds()throws Exception{byte[] data=JSON.toJSONBytes(List.of(Map.of("oper_id",1)));Path file=root.resolve("test.gz");try(var zip=new GZIPOutputStream(Files.newOutputStream(file))){zip.write(data);}String digest=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));AuditRetention service=service(mock(JdbcTemplate.class));assertThrows(IOException.class,()->service.verifyArchive(file,"oper_id",List.of("1"),"wrong"));assertThrows(IOException.class,()->service.verifyArchive(file,"oper_id",List.of("1","2"),digest));assertThrows(IOException.class,()->service.verifyArchive(file,"oper_id",List.of("2"),digest));}
}
